// ponytail: hand-rolled runtime service worker. vite-plugin-pwa's Workbox SW
// generation doesn't fire under Vite 8 + @cloudflare/vite-plugin's named ssr
// environment, so we ship a tiny SW directly. It does three things:
//
//   1. PRECACHE the app shell at install — so a cold open offline boots the
//      app. The shell (/_shell.html) is generated by tanstackStart({spa}) at
//      build time as an empty app document (no route data); the router takes
//      over client-side once it loads.
//   2. NAVIGATION FALLBACK — any document navigation that can't be served
//      from cache falls back to the cached shell, so the app always boots
//      instead of showing the browser's offline error page.
//   3. RUNTIME caching for same-origin GETs — but NOT uniformly: build-hashed
//      assets are cache-first (SWR), public /media binaries are cached for
//      offline replay (private credential media is bypassed entirely), and GET
//      server-fn RPC responses are NETWORK-FIRST (cookie-dependent).
//      Last-known data (directory list, session, etc.) is still served offline
//      as the fallback. Mutations are POST and never enter here.
//
// The shell's build-hashed CSS/JS are precached at install by parsing the
// shell HTML for its own /assets/*.{css,js} URLs (see install below). Without
// this, cache-first navigation served the shell instantly while CSS round-
// tripped the network → a flash of unstyled (text-only) content on slow
// connections. The shell is the source of truth for its own hashes, so no
// build-time precache manifest is needed. Route chunks lazy-loaded after
// hydration are still covered by runtime SWR.
//
// CACHE mirrors the app version in package.json. `__SW_VERSION__` is a
// placeholder rewritten at build time by `swVersionPlugin` in vite.config.ts
// (generateBundle hook) — every `npm version ...` automatically bumps the SW
// cache key, force-invalidating installed PWA clients. No hand-edit needed.
// For backward-compatible releases, SWR + skipWaiting still refreshes
// content within one reload without a cache-name change.
const CACHE = `psico-support-${__SW_VERSION__}`

// ponytail: the static SPA shell generated at build time. Served on cold-open
// offline and as the navigation fallback. Use the canonical /_shell URL (the
// .html form 307-redirects to this); avoids the SW caching a redirect.
const SHELL = '/_shell'
// ponytail: static Spanish fallback served when navigation OR a build-hashed
// asset (/assets/*.{js,css}) fails to load after a deploy. The classic broken-
// PWA symptom — dead chunk URL → blank/500 with no UI — is intercepted here
// before it reaches React. The page auto-reloads to '/' (meta-refresh + JS),
// by which point the new SW has finished activating + precaching the new
// shell. See public/actualizando.html for the page itself.
const FALLBACK = '/actualizando.html'
const PRECACHE = [
  SHELL,
  FALLBACK,
  '/manifest.webmanifest',
  '/logo192.png',
  '/logo512.png',
  '/favicon.ico',
]

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE)
      // best-effort: addAll rejects if any single fetch fails; cache each so
      // one missing icon doesn't block the shell.
      await Promise.allSettled(PRECACHE.map((url) => cache.add(url)))
      // Precache the shell's own build-hashed CSS/JS. The shell HTML already
      // references its exact asset hashes, so parse them out and cache.addAll
      // them — no build-time manifest injection needed. This is what prevents
      // the FOUC: without it, cache-first navigation paints the shell while
      // CSS/JS round-trip the network (visible as unstyled text on slow links).
      // cache.match returns a fresh clone, so consuming .text() here does NOT
      // evict the cached shell entry.
      try {
        const shellRes = await cache.match(SHELL)
        if (shellRes) {
          const html = await shellRes.text()
          await Promise.allSettled(
            shellAssetUrls(html).map((url) => cache.add(url)),
          )
        }
      } catch {
        /* best-effort; runtime SWR still covers assets on later visits */
      }
      self.skipWaiting()
    })(),
  )
})

// ponytail: extract the shell's hashed stylesheet + script URLs for precaching.
// Matches root-relative /assets/*.{css,js} in href/src — covers the stylesheet
// <link>, <script src>, and modulepreload <link href>. Ignores cross-origin
// and non-/assets/ URLs (favicon etc. are already in PRECACHE).
function shellAssetUrls(html) {
  const urls = new Set()
  const re = /(?:href|src)="(\/assets\/[^"]+\.(?:css|js))"/g
  let m
  while ((m = re.exec(html))) urls.add(m[1])
  return [...urls]
}

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(
        keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)),
      )
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('fetch', (event) => {
  const req = event.request
  if (req.method !== 'GET') return
  const reqUrl = new URL(req.url)
  const sameOrigin = reqUrl.origin === self.location.origin
  if (!sameOrigin) return

  // ponytail: NEVER intercept /api/auth/* (Better Auth). These are API
  // endpoints, not app routes — they return redirects (the password-reset
  // callback GET /reset-password/:token → 302 to /recuperar?token=…), JSON,
  // and set auth cookies, none of which the SW should cache or replay.
  //
  // This is load-bearing for password recovery: the email link points at
  // /api/auth/reset-password/:token?callbackURL=… and is opened as a browser
  // navigation. If the SW's navigation branch (below) ran for it, it would
  // find the precached shell via cache.match(SHELL) and return it instantly
  // (cache-first: `return cached || network`), so the browser would render
  // the shell at the reset-callback URL and Better Auth's 302 to
  // /recuperar?token=… would NEVER execute — the router would hydrate
  // against /api/auth/reset-password/:token (a server-only route with no
  // component) and the page would be blank. Letting these requests bypass
  // the SW means the browser follows the 302 itself, lands on
  // /recuperar?token=… (a real app route the SW then shells correctly), and
  // the recovery form renders. Same reasoning protects any future GET
  // callbacks (email verification, OAuth) without further SW edits.
  //
  // ponytail: PRIVATE credential media — /media/certificate/* (admin-only)
  // and /media/document/* (owner-or-admin) — are also bypassed, never cached.
  // These routes serve personal credential documents and deliberately emit
  // `Cache-Control: private, max-age=60` so a doc doesn't linger on a shared
  // device after logout — but the Cache API ignores Cache-Control and this SW
  // used to cache their 200s in the runtime SWR branch and replay them
  // cache-first with NO auth check: after logout (or as a different account on
  // the same browser profile) the cached bytes served straight from the SW,
  // defeating the route's gate entirely. Offline replay of private credentials
  // is not a feature, so: never intercept, never cache. Public media
  // (/media/avatar/*, /media/audio/*) stay SWR-cached by design — see the
  // route comments.
  if (
    reqUrl.pathname.startsWith('/api/auth/') ||
    reqUrl.pathname.startsWith('/media/certificate/') ||
    reqUrl.pathname.startsWith('/media/document/')
  )
    return

  // ponytail: server-fn RPC GETs are NETWORK-FIRST, not cache-first. TanStack
  // Start's client fetcher tags every server-fn call with the x-tsr-serverFn
  // request header, so this reliably identifies RPC traffic. Their responses
  // can depend on the session cookie (getCurrentUser, amIAdmin,
  // getMyProfessional, my appointments/follow-ups, …) and the Cache API does
  // NOT vary on cookies — a cached anonymous response (null / false) was
  // replayed to a freshly-logged-in user, so /cuenta rendered the logged-out
  // view and the admin card stayed hidden until a manual reload (the old SWR
  // branch's background revalidation only fixed the NEXT visit's cache — the
  // current caller had already received the stale response). Network-first
  // keeps the cached copy purely as the OFFLINE fallback (successful 200s are
  // still cached) while guaranteeing online callers always get fresh,
  // session-accurate data. Build-hashed assets (immutable) and /media
  // binaries (public R2 reads) keep the cache-first SWR branch below.
  // Ceiling: online callers now always pay the full RPC round-trip (no
  // serve-stale). If that proves costly on slow links, upgrade to
  // stale-while-revalidate-with-short-TTL — never plain cache-first.
  if (req.headers.get('x-tsr-serverFn') === 'true') {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE)
        const cached = await cache.match(req)
        const fallback = cached || Response.error()
        return fetch(req)
          .then((res) => {
            if (res && res.status === 200) cache.put(req, res.clone())
            return res
          })
          .catch(() => fallback)
      })(),
    )
    return
  }

  // ponytail: document navigations are NETWORK-FIRST (see return below): the
  // worker serves real SSR HTML online, cached here on success for the next
  // visit — so real content paints immediately instead of an empty shell.
  // When the network is unavailable, the .catch falls back to the cached
  // per-URL response or the precached shell, which is what boots the app
  // offline from a cold start.
  //
  // /media/* URLs are EXCLUDED from navigation fallback: they're binary R2
  // reads (avatars, audio, certificates, support docs) served by server-only
  // route handlers with NO client route component. If the SW fell back to the
  // shell for one of these, the router would hydrate against a path with no
  // matching route → TanStack's hydrate() invariant throws (WEB-C). Let these
  // go straight to the network always; the runtime-SWR branch below still
  // caches successful 200s for offline replay.
  //
  // If the network rejects AND there's no per-URL cache AND the shell isn't
  // cached (e.g. brand-new install where install hasn't completed, or all
  // caches were just evicted by activate), serve the static Spanish fallback
  // page — never let the navigation fail to the browser's offline/blank page.
  if (req.mode === 'navigate' && !new URL(req.url).pathname.startsWith('/media/')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(CACHE)
        // Prefer a cached response for THIS exact URL (e.g. a visited SSR
        // profile), else fall back to the shell so the app still mounts.
        const cached = (await cache.match(req)) || (await cache.match(SHELL))
        const fallback =
          cached || (await cache.match(FALLBACK)) || Response.error()
        const network = fetch(req)
          .then((res) => {
            if (res && res.status === 200) cache.put(req, res.clone())
            return res
          })
          .catch(() => fallback)
        // ponytail: NETWORK-FIRST for navigations. The empty shell is always
        // precached, so a cache-first policy (the old `return cached || network`)
        // returned the empty shell on EVERY first visit and only showed real
        // content after client-side hydration — every route looked blank on
        // first paint, and the real SSR HTML was fetched in the background
        // then discarded (cached only for the NEXT visit, which is why reload
        // worked). Network-first honors SSR: online users get real HTML
        // immediately; `network`'s .catch(() => fallback) above still returns
        // the cached shell / per-URL entry when offline, so cold-boot offline
        // is preserved. Ceiling: on very slow links this waits for the worker
        // round-trip before painting — upgrade to a race-with-timeout (network
        // if it resolves in ~300ms, else cached shell) if that proves worse
        // than the old instant-shell-then-hydrate.
        return network
      })(),
    )
    return
  }

  // ponytail: everything else (build-hashed assets, /media binaries, other
  // same-origin GETs) — runtime SWR.
  //
  // NOTE: dead /assets/*.{js,css} chunks after a deploy (the OLD app shell
  // still running in an open tab asking for a hashed URL that no longer
  // exists on the origin) are intentionally NOT special-cased here. The
  // runtime SWR branch below returns the 404 (or network error) unchanged;
  // the dynamic-import promise then rejects with "Failed to fetch dynamically
  // imported module" / "Unable to preload CSS for …", and the client-side
  // recovery in src/lib/pwa-update.ts (CHUNK_ERR_PATTERNS + the Vite
  // `vite:preloadError` event listener) catches it and reloads once onto
  // the new build. Returning an HTML fallback for a script-style request
  // would change the error to a MIME-mismatch message that doesn't match
  // the recovery patterns — actively defeating the client handler.
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE)
      const cached = await cache.match(req)
      const network = fetch(req)
        .then((res) => {
          if (res && res.status === 200) cache.put(req, res.clone())
          return res
        })
        .catch(() => cached)
      return cached || network
    })(),
  )
})
